import{_ as t,a as e}from"./chunks/description-1.Hseqjb9Z.js";import{_ as n,o as r,c as i,a5 as o}from"./chunks/framework.CcrBcQWS.js";const b=JSON.parse('{"title":"Battery Handling Precautions","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/safety/battery-handling.md","filePath":"manual/safety/battery-handling.md","lastUpdated":1787021357000}'),s={name:"manual/safety/battery-handling.md"};function g(l,a,d,c,h,p){return r(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="battery-handling-precautions" tabindex="-1">Battery Handling Precautions <a class="header-anchor" href="#battery-handling-precautions" aria-label="Permalink to &quot;Battery Handling Precautions&quot;">​</a></h1><p>Safe handling, charging, and storage of the RBQ’s on-board battery. For replacement steps, see <a href="/RBQ/nightly/manual/maintenance/battery.html">Battery Replacement</a>.</p><h2 id="charging" tabindex="-1">Charging <a class="header-anchor" href="#charging" aria-label="Permalink to &quot;Charging&quot;">​</a></h2><figure><img src="'+t+'" alt="Charging with RBQ10 dedicated charger"><img src="'+e+'" alt="Charging with RBQ10 docking station"><figcaption style="text-align:center;">[ Use only the designated charger and docking station. ]</figcaption></figure><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">WARNING</p><p>1) Charge only with the RBQ10 dedicated charger or RBQ10 docking station. Other chargers can cause overcharge, overheating, or fire.<br>2) While charging, keep the robot and charger away from flammables and heat sources.<br>3) Do not use damaged chargers or cables.</p></div></div><p>Charging steps are described on the <a href="/RBQ/nightly/manual/operation/charging.html">Charging</a> page.</p><ul><li><strong>Fully discharged</strong>: If the robot is fully discharged and will not power on, the docking station may not charge it. In that case, connect the supplied external charger directly to the charging port.</li></ul><h2 id="handling-and-storage" tabindex="-1">Handling and storage <a class="header-anchor" href="#handling-and-storage" aria-label="Permalink to &quot;Handling and storage&quot;">​</a></h2><ul><li><strong>Impact and penetration</strong>: Do not drop the battery, puncture it, or submerge it. Do not use a damaged battery; contact Rainbow Robotics.</li><li><strong>Temperature</strong>: Stay within the specified storage and use temperature range. Do not expose to high heat, direct sunlight, or heaters.</li><li><strong>Storage</strong>: Do not store the battery upside down. If unused for a long time, check its condition periodically.</li></ul><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">WARNING</p><p><strong>Battery removal when not in use</strong>: When not in use, <strong>remove the battery</strong> for storage. Leaving the battery installed in a powered-off robot for <strong>more than 24 hours</strong> can cause <strong>irreversible damage</strong>.</p></div></div>',10)])])}const f=n(s,[["render",g]]);export{b as __pageData,f as default};
